{
  "problem_id": "C2",
  "input_format": {
    "description": "First line contains integer t, number of test cases. Each test case: first line three integers n, y, x; second line contains y distinct integers from 1 to n.",
    "format_type": "multi_line",
    "fields": [
      {
        "name": "t",
        "type": "integer",
        "dimension": null,
        "position": 1
      },
      {
        "name": "n",
        "type": "integer",
        "dimension": null,
        "position": 2 (per test case)
      },
      {
        "name": "y",
        "type": "integer",
        "dimension": null,
        "position": 2 (per test case)
      },
      {
        "name": "x",
        "type": "integer",
        "dimension": null,
        "position": 2 (per test case)
      },
      {
        "name": "vertices",
        "type": "list_int",
        "dimension": "length y",
        "position": 3 (per test case)
      }
    ]
  },
  "output_format": {
    "description": "For each test case output a single integer: the maximum number of triangular pieces.",
    "format_type": "single_line"
  },
  "constraints": {
    "explicit": [
      {
        "variable": "n",
        "lower_bound": 3,
        "upper_bound": null,
        "type": "integer",
        "description": "number of sides of the polygon"
      },
      {
        "variable": "y",
        "lower_bound": 3,
        "upper_bound": "min(n, 2e5)",
        "type": "integer",
        "description": "number of vertices Bessie has chosen"
      },
      {
        "variable": "x",
        "lower_bound": 0,
        "upper_bound": null,
        "type": "integer",
        "description": "maximum number of additional vertices you can choose"
      },
      {
        "variable": "sum_y",
        "lower_bound": null,
        "upper_bound": 200000,
        "type": "integer",
        "description": "sum of y over all test cases"
      }
    ],
    "time_limit_seconds": null,
    "memory_limit_mb": null
  },
  "implicit_constraints": [
    {
      "description": "Vertices are distinct and between 1 and n inclusive.",
      "type": "domain_knowledge",
      "triggered_by": "Problem statement: distinct integers from 1 to n"
    },
    {
      "description": "Additional vertices must be chosen from vertices not already chosen by Bessie, so effective maximum additional vertices is min(x, n-y).",
      "type": "logical_constraint",
      "triggered_by": "The problem says 'choose no more than x other vertices', but only unchosen vertices are available."
    }
  ],
  "boundary_conditions": [
    {
      "variable": "x",
      "values": [0],
      "condition": "minimum"
    },
    {
      "variable": "y",
      "values": [3],
      "condition": "minimum"
    },
    {
      "variable": "n",
      "values": [3],
      "condition": "minimum"
    },
    {
      "variable": "y",
      "values": ["n"],
      "condition": "maximum (all vertices chosen)"
    },
    {
      "variable": "x",
      "values": ["n - y"],
      "condition": "maximum effective additional vertices"
    }
  ],
  "special_cases": [
    {
      "description": "When x is larger than the number of available vertices, we can only choose all remaining vertices.",
      "test_values": "x >= n - y",
      "expected_behavior": "Can choose all remaining vertices, giving maximum triangles possible.",
      "common_mistakes": "Assuming x is always achievable; not capping at n-y."
    },
    {
      "description": "When all vertices are already chosen (y = n), no additional vertices can be chosen.",
      "test_values": "y = n",
      "expected_behavior": "Only triangles formed from initial vertices.",
      "common_mistakes": "Trying to select more vertices."
    },
    {
      "description": "Small n (e.g., n=3) with y=3: only triangle possible.",
      "test_values": "n=3, y=3, x=0",
      "expected_behavior": "Output 1 (the whole polygon is a triangle).",
      "common_mistakes": "Dividing by arcs incorrectly."
    },
    {
      "description": "Large gaps between chosen vertices and large x available: ability to create many triangles.",
      "test_values": "n large, y small, x large",
      "expected_behavior": "Greedy selection in largest gaps yields optimal count.",
      "common_mistakes": "Not sorting gaps or not using a priority queue."
    }
  ],
  "problem_type_analysis": {
    "category": "Geometry",
    "sub_category": "Convex Polygon Triangulation",
    "key_operations": [
      "Sort chosen vertices",
      "Compute gaps between consecutive chosen vertices (wrap around)",
      "For each gap, compute number of triangles that can be formed from that arc",
      "Greedily select additional vertices in largest gaps to increase triangle count"
    ],
    "common_pitfalls": [
      "Not considering the wrap-around gap",
      "Incorrect formula for number of triangles from a gap",
      "Not capping the number of additional vertices by available unchosen vertices",
      "Forgetting that triangles must be formed by diagonals that do not intersect (only within arcs)"
    ]
  }
}

{
  "problem_id": "G. Extra Transition",
  "input_format": {
    "description": "First line contains integer t. Each test case: first line n m, second line n integers w_i, then m lines each with two integers u v (1-indexed levels).",
    "format_type": "multi_line",
    "fields": [
      {
        "name": "t",
        "type": "integer",
        "dimension": null,
        "position": "1"
      },
      {
        "name": "n",
        "type": "integer",
        "dimension": null,
        "position": "first line of each test case, first number"
      },
      {
        "name": "m",
        "type": "integer",
        "dimension": null,
        "position": "first line of each test case, second number"
      },
      {
        "name": "w",
        "type": "list_int",
        "dimension": "length n",
        "position": "second line of each test case"
      },
      {
        "name": "edges",
        "type": "matrix_int",
        "dimension": "m x 2",
        "position": "next m lines of each test case"
      }
    ]
  },
  "output_format": {
    "description": "For each test case, output either the string 'bad' or the computed sum (as an integer). One line per test case.",
    "format_type": "multi_line"
  },
  "constraints": {
    "explicit": [
      {
        "variable": "n",
        "lower_bound": 2,
        "upper_bound": 200000,
        "type": "integer",
        "description": "number of levels per test case (maximum based on sum of n across test cases ≤ 2e5)"
      },
      {
        "variable": "m",
        "lower_bound": 1,
        "upper_bound": 200000,
        "type": "integer",
        "description": "number of transitions per test case (maximum based on sum of m across test cases ≤ 2e5)"
      },
      {
        "variable": "w_i",
        "lower_bound": 0,
        "upper_bound": null,
        "type": "integer",
        "description": "weight of level i"
      },
      {
        "variable": "sum of n across test cases",
        "lower_bound": null,
        "upper_bound": 200000,
        "type": "integer",
        "description": "total number of levels across all test cases"
      },
      {
        "variable": "sum of m across test cases",
        "lower_bound": null,
        "upper_bound": 200000,
        "type": "integer",
        "description": "total number of transitions across all test cases"
      }
    ],
    "time_limit_seconds": null,
    "memory_limit_mb": null
  },
  "implicit_constraints": [
    {
      "description": "The transition network is connected for each test case, as guaranteed by input.",
      "type": "logical_constraint",
      "triggered_by": "explicit statement in input description"
    },
    {
      "description": "Levels are 1-indexed from 1 to n.",
      "type": "logical_constraint",
      "triggered_by": "problem description"
    },
    {
      "description": "The sum of weights can be as large as 10^9 * 2e5, requiring 64-bit integers (e.g., Python int or C++ long long).",
      "type": "efficiency_hint",
      "triggered_by": "large n and w_i may be up to 10^9"
    }
  ],
  "boundary_conditions": [
    {
      "variable": "n",
      "values": [2, 200000],
      "condition": "minimum and maximum number of levels"
    },
    {
      "variable": "m",
      "values": [1, 200000],
      "condition": "minimum and maximum number of transitions"
    },
    {
      "variable": "w_i",
      "values": [0, 10^9],
      "condition": "minimum and possible maximum weight"
    },
    {
      "variable": "t",
      "values": [1, 200000],
      "condition": "number of test cases may be up to 2e5 when n,m are small"
    }
  ],
  "special_cases": [
    {
      "description": "Network that is not well-designed, e.g., due to lack of a successful path containing some level or violation of the ordering condition.",
      "test_values": "Example: test case 2 with n=3, edges (1-3,2-3). Level 1 has no successful path containing it (since cannot reach level 3 without repeating?).",
      "expected_behavior": "Output 'bad' for that test case.",
      "common_mistakes": "Assuming all networks are well-designed; not handling the case where the network is not well-designed."
    },
    {
      "description": "Network with only two levels (n=2). Then the only possible extra transition is between 1 and 2, but if already connected, no candidate; if not connected, adding it may or may not keep property.",
      "test_values": "n=2, m=0 (disconnected? but input guarantees connectivity, so m≥1). So n=2, m=1 means already edge.",
      "expected_behavior": "If n=2, network is a single edge, then set S is empty because the only pair is already directly connected. Sum is 0.",
      "common_mistakes": "Incorrectly computing sum when S is empty."
    },
    {
      "description": "Large weights leading to integer overflow if using 32-bit integers.",
      "test_values": "w_i up to 10^9, n up to 2e5, sum of products may exceed 2^31.",
      "expected_behavior": "Use 64-bit integer (e.g., long long in C++ or int in Python).",
      "common_mistakes": "Using 32-bit int and getting overflow."
    }
  ],
  "problem_type_analysis": {
    "category": "graphs",
    "sub_category": "graph properties and counting",
    "key_operations": [
      "Check if graph is well-designed (likely equivalent to graph being a series-parallel graph or having a specific structure)",
      "Identify all pairs of vertices (u,v) not directly connected such that adding an edge keeps the graph well-designed",
      "Compute sum over all such pairs of w_u * w_v"
    ],
    "common_pitfalls": [
      "Misinterpreting the definition of well-designed",
      "Inefficiently checking all pairs (O(n^2) impossible due to n up to 2e5)",
      "Forgetting that the network must remain connected after adding the extra transition? (Not explicitly required but implied by connectivity of original network? Actually extra transition is bidirectional, adding it keeps connectivity.)",
      "Integer overflow"
    ]
  }
}

