{
  "problem_id": "E",
  "input_format": {
    "description": "First line: integer n (number of shelves). Second line: n integers a_i (number of honey pots per shelf). Third line: integer q (number of actions). Then q lines each with three integers u, v, k (shelf from which Winnie took pots, shelf to which he put them, number of pots taken).",
    "format_type": "multi_line",
    "fields": [
      {
        "name": "n",
        "type": "integer",
        "dimension": null,
        "position": 1
      },
      {
        "name": "a_i",
        "type": "list_int",
        "dimension": "length n",
        "position": 2
      },
      {
        "name": "q",
        "type": "integer",
        "dimension": null,
        "position": 3
      },
      {
        "name": "actions",
        "type": "list_int",
        "dimension": "q rows of 3 integers",
        "position": "4 to 3+q"
      }
    ]
  },
  "output_format": {
    "description": "For each action, output the mathematical expectation m (number of shelves with no untasted pot) with absolute or relative error up to 1e-9. Output one number per line.",
    "format_type": "multi_line"
  },
  "constraints": {
    "explicit": [
      {
        "variable": "n",
        "lower_bound": 1,
        "upper_bound": 100000,
        "type": "integer",
        "description": "Number of shelves"
      },
      {
        "variable": "a_i",
        "lower_bound": 0,
        "upper_bound": 100,
        "type": "integer",
        "description": "Initial number of pots on shelf i"
      },
      {
        "variable": "q",
        "lower_bound": 1,
        "upper_bound": 100000,
        "type": "integer",
        "description": "Number of actions"
      },
      {
        "variable": "u_i, v_i",
        "lower_bound": 1,
        "upper_bound": 100000,
        "type": "integer",
        "description": "Shelf indices"
      },
      {
        "variable": "k_i",
        "lower_bound": 1,
        "upper_bound": 5,
        "type": "integer",
        "description": "Number of pots taken"
      }
    ],
    "time_limit_seconds": null,
    "memory_limit_mb": null
  },
  "implicit_constraints": [
    {
      "description": "Winnie never takes more pots than available on the shelf at that moment, so the process is valid.",
      "type": "logical_constraint",
      "triggered_by": "problem statement guarantee"
    },
    {
      "description": "Since k_i <= 5, the number of pots moved per action is small, enabling DP over small state space.",
      "type": "efficiency_hint",
      "triggered_by": "constraint on k"
    },
    {
      "description": "a_i <= 100, so the total number of pots per shelf is limited, allowing O(n * max_a) solutions.",
      "type": "efficiency_hint",
      "triggered_by": "constraint on a_i"
    },
    {
      "description": "n and q up to 1e5, so total operations should be O((n+q) * log something) or O((n+q) * small_constant).",
      "type": "efficiency_hint",
      "triggered_by": "large constraints"
    }
  ],
  "boundary_conditions": [
    {
      "variable": "n",
      "values": [1, 100000],
      "condition": "minimum and maximum number of shelves"
    },
    {
      "variable": "a_i",
      "values": [0, 100],
      "condition": "minimum and maximum initial pots"
    },
    {
      "variable": "q",
      "values": [1, 100000],
      "condition": "minimum and maximum number of actions"
    },
    {
      "variable": "k_i",
      "values": [1, 5],
      "condition": "minimum and maximum pots taken per action"
    }
  ],
  "special_cases": [
    {
      "description": "Shelf with zero pots initially: no untasted pots, but after actions pots may be moved.",
      "test_values": "a_i = 0 for some shelf",
      "expected_behavior": "Initially that shelf contributes 1 to m (since no untasted pot means all pots are tasted? Actually definition: shelves that don't have a single untasted pot. If a shelf has no pots, vacuously it has no untasted pot, so it counts as such. But careful: if no pots, it is a shelf with no untasted pot. So initial expectation includes shelves with zero pots. After moving pots, a shelf may gain pots, some tasted, some untasted. Need to handle correctly.",
      "common_mistakes": "Assuming a shelf with zero pots does not count toward m, or miscounting when pots are moved."
    },
    {
      "description": "All pots are tasted initially? No, initially all pots are untasted. So initially m = 0? Actually if all pots are untasted, then each shelf has at least one untasted pot (if non-zero). But shelves with zero pots have no untasted pot, so they count. So initial m = number of shelves with a_i = 0.",
      "test_values": "All a_i = 0, then initial m = n.",
      "expected_behavior": "Initial expectation is n. After actions, if pots are moved, they are tasted, so shelves receiving pots get tasted pots. But the pots themselves become tasted, so they contribute to untasted? Wait: when Winnie tastes a pot, he eats honey? Actually he tastes from each pot, so those pots become tasted. He then puts the tasted pots on another shelf. So after action, the pots on the source shelf are reduced by k (all tasted), and the destination shelf gains k tasted pots. So the number of untasted pots on source decreases by k (since those k were tasted and removed), and on destination, the untasted count unchanged (since added pots are tasted). So we need to track for each shelf the number of untasted pots. Initially all pots are untasted, so untasted = a_i. After each action, we sample k pots uniformly from the untasted pots on source? Actually he chooses k pots from shelf u uniformly among all sets of k pots on that shelf. If some pots are already tasted, are they distinguishable? He chooses among all pots on the shelf, not distinguishing tasted vs untasted? The problem says "among all sets of k_i pots on shelf u_i, he equiprobably chooses one." So he selects any k pots uniformly from the total pots on that shelf (both tasted and untasted). Then he tastes them (so those become tasted) and puts them on shelf v. So the process is: from shelf u with total pots total_u, he picks a random set of size k uniformly from all pots (total choose k), tastes them (so they become tasted), and moves them to v. So the number of untasted pots on u decreases by the number of untasted pots among the chosen set. That's a random variable. So expectation requires careful probability update. This is a classic problem of expectation of number of shelves with zero untasted pots after a series of random transfers. The constraints (k <=5) hint at DP on small values.",
      "common_mistakes": "Confusing total pots with untasted pots; assuming that pots are indistinguishable; not handling uniform selection among sets."
    }
  ],
  "problem_type_analysis": {
    "category": "Probabilities and Expected Value",
    "sub_category": "Dynamic Programming with Expected Value",
    "key_operations": [
      "Maintain for each shelf the distribution of untasted pots count (0 to a_i) after each action",
      "Compute expected number of shelves with zero untasted pots as sum over shelves of probability that shelf has zero untasted pots",
      "Update probabilities for source and destination shelves after each action using combinatorial probability",
      "Process queries online"
    ],
    "common_pitfalls": [
      "Incorrect probability update formulas",
      "Inefficient O(n * max_a) updates per query",
      "Floating point precision accumulation",
      "Not handling shelves with zero pots correctly"
    ]
  }
