{
  "problem_id": "B",
  "input_format": {
    "description": "A single line containing a string of letters 'a' and 'b'.",
    "format_type": "single_line",
    "fields": [
      {
        "name": "s",
        "type": "string",
        "dimension": "length from 1 to 1e6",
        "position": 1
      }
    ]
  },
