    "description": "A single integer representing the minimum number of steps modulo 1e9+7.",
    "format_type": "single_line"
  },
  "constraints": {
    "explicit": [
      {
        "variable": "s",
        "lower_bound": 1,
        "upper_bound": 1000000,
        "type": "string",
        "description": "Length of string"
      }
    ],
    "time_limit_seconds": null,
    "memory_limit_mb": null
  },
  "implicit_constraints": [
    {
      "description": "The string consists only of characters 'a' and 'b', no other characters.",
      "type": "logical_constraint",
      "triggered_by": "Problem statement explicitly says 'letters a and b only'."
    },
    {
      "description": "The output must be computed modulo 1e9+7, indicating large numbers possible.",
      "type": "efficiency_hint",
      "triggered_by": "Output modulo 10^9+7 and string length up to 1e6 implies O(n) solution with modular arithmetic."
    }
  ],
